/* === report_struct table data === */
-- Regular report
INSERT INTO report_struct (
  report_id, sect_id, parent_sect_id, s_ord, toc_cap, tbl_cap, feature, function_name,
  content, sect_struct)
VALUES
(1, 'rep_details', NULL, 10, 'Сведения об отчёте', 'Сведения об отчёте', NULL, NULL, NULL,
  '[{'
    '"type": "row_table",'
    '"source": "properties",'
    '"columns": ['
        '{"id": "pgprofile_version", "class": "table_obj_value", "caption": "Версия"},'
        '{"id": "server_name", "class": "table_obj_value", "caption": "Имя сервера"},'
        '{"caption": "Интервал (снимки)", "class": "table_obj_value", "columns": ['
          '{"id": "start1_id", "class": "table_obj_value", "caption": "начало"},'
          '{"id": "end1_id", "class": "table_obj_value", "caption": "конец"}'
        ']},'
        '{"caption": "Интервал (время)", "class": "table_obj_value", "columns": ['
          '{"id": "report_start1", "class": "table_obj_value", "caption": "начало"},'
          '{"id": "report_end1", "class": "table_obj_value", "caption": "конец"}'
        ']}'
    ']}'
  ']'::jsonb),
(1, 'rep_settings', NULL, 11, NULL, NULL, NULL, NULL, NULL,
  '[{'
    '"type": "row_table",'
    '"source": "settings",'
    '"filter": {"type": "exists", "field": "h_ord"},'
    '"ordering": "h_ord",'
    '"columns": ['
      '{"caption": "Параметр", "id": "name", "class": "table_obj_name"},'
      '{"caption": "Значение", "id": "reset_val", "class": "table_obj_value"}'
    ']'
  '}]'::jsonb),
(1, 'stmt_cmt1', NULL, 100, NULL, NULL, 'stmt_cnt_range', NULL,
  '{"class": "warning", "text": "На этом интервале есть снимки, в которых число собранных операторов превышает 90% значения pg_stat_statements.max. '
  'Рекомендуется увеличить параметр pg_stat_statements.max"}',
  '[{'
  '"type": "row_table", '
  '"source": "stmt_cnt_range",'
  '"ordering": "sample_id",'
  '"columns": ['
      '{"id": "sample_id", "class": "table_obj_value", "caption": "ID снимка"}, '
      '{"id": "sample_time", "class": "table_obj_value", "caption": "Время снимка"}, '
      '{"id": "stmt_cnt", "class": "table_obj_value", "caption": "Собрано операторов"}, '
      '{"id": "max_cnt", "class": "table_obj_value", "caption": "pg_stat_statements.max"}'
  ']}]'::jsonb),
(1, 'srvstat', NULL, 200, 'Статистика сервера', 'Статистика сервера', NULL, NULL, NULL, NULL),
(1, 'actsesshdr', NULL, 250, 'Состояния сеансов', 'Состояния сеансов по данным подснимков', 'act_backend', NULL,
  '{"class": "notice", "text": "Статистика состояний сеансов, превысивших пороги сбора."}', NULL),
(1, 'blocking_tree', NULL, 260, 'Блокировки', 'Деревья блокировок', 'blocking_tree', NULL,
  '{"class": "notice", "text": "Корневая строка — блокирующий сеанс. Вложенные строки — ожидающие запросы. В колонках «Ожидает PID», «Блокирует PID» и «Текущий запрос сеанса» видно направление блокировки и участвующие SQL-запросы. Нажмите стрелку, чтобы раскрыть цепочку."}',
  '[{'
    '"type": "row_table",'
    '"source": "blocking_tree",'
    '"ordering": "ord_tree",'
    '"class": "lock-tree",'
    '"columns": ['
      '{"id": "node_label", "class": "table_obj_name lockTreeNode", "caption": "Сеанс"},'
      '{"id": "role_label", "class": "table_obj_name", "caption": "Роль в цепочке"},'
      '{"id": "blocked_by", "class": "table_obj_value", "caption": "Ожидает PID"},'
      '{"id": "blocks_pids", "class": "table_obj_value", "caption": "Блокирует PID"},'
      '{"id": "observed_at", "class": "table_obj_value", "caption": "Время наблюдения"},'
      '{"id": "dbname", "class": "table_obj_name", "caption": "База данных"},'
      '{"id": "username", "class": "table_obj_name", "caption": "Пользователь"},'
      '{"id": "application_name", "class": "table_obj_name", "caption": "Приложение"},'
      '{"id": "client_addr", "class": "table_obj_value", "caption": "Клиент"},'
      '{"id": "xact_age", "class": "table_obj_value", "caption": "Возраст транзакции"},'
      '{"id": "session_state", "class": "table_obj_name", "caption": "Состояние"},'
      '{"id": "wait_event", "class": "table_obj_name", "caption": "Ожидание"},'
      '{"id": "lock_info", "class": "table_obj_name", "caption": "Ожидаемая блокировка"},'
      '{"id": "query_text", "class": "table_obj_name fullScreen", "caption": "Текущий запрос сеанса"}'
    ']'
  '}]'::jsonb),
(1, 'sqlsthdr', NULL, 300, 'Статистика SQL-запросов', 'Статистика SQL-запросов', 'statstatements', NULL, NULL, NULL),
(1, 'objects', NULL, 400, 'Статистика объектов схемы', 'Статистика объектов схемы', NULL, NULL, NULL, NULL),
(1, 'funchdr', NULL, 500, 'Статистика пользовательских функций', 'Статистика пользовательских функций', 'function_stats', NULL, NULL, NULL),
(1, 'vachdr', NULL, 600, 'Статистика очистки', 'Статистика очистки', NULL, NULL, NULL, NULL),
(1, 'settings', NULL, 700, 'Параметры кластера', 'Параметры кластера на интервале отчёта', NULL, NULL, NULL, NULL),
(1, 'extensions', NULL, 750, 'Версии расширений', 'Версии расширений на интервале отчёта', NULL, NULL, NULL, NULL),
(1, 'stmt_warn', NULL, 800, NULL, 'Предупреждение!', 'stmt_cnt_all', NULL, NULL,
  '[{'
    '"type": "row_table", '
    '"source": "stmt_cnt_all",'
    '"ordering": "sample_id",'
    '"columns": ['
        '{"id": "sample_id", "class": "table_obj_value", "caption": "ID снимка"}, '
        '{"id": "sample_time", "class": "table_obj_value", "caption": "Время снимка"}, '
        '{"id": "stmt_cnt", "class": "table_obj_value", "caption": "Собрано операторов"}, '
        '{"id": "max_cnt", "class": "table_obj_value", "caption": "pg_stat_statements.max"}'
    ']}]'::jsonb)
;

-- Server section of regular report
INSERT INTO report_struct (
  report_id, sect_id, parent_sect_id, s_ord, toc_cap, tbl_cap, feature, function_name,
  content, sect_struct)
VALUES
(1, 'dbstat', 'srvstat', 100, 'Статистика баз данных', 'Статистика баз данных', NULL, NULL, NULL, NULL),
(1, 'dbstatreset', 'dbstat', 200, NULL, NULL, 'dbstats_reset', NULL,
  '{"class": "warning", "text": "На интервале отчёта обнаружен сброс статистики баз данных! Значения для перечисленных баз данных и содержащихся в них объектов могут быть искажены"}',
  '[{'
    '"type": "row_table",'
    '"source": "dbstats_reset",'
    '"ordering": "ord_sample",'
    '"columns": ['
      '{"caption": "База данных", "id": "dbname", "class": "table_obj_name"},'
      '{"caption": "Снимок", "id": "sample_id", "class": "table_obj_value"},'
      '{"caption": "Время сброса", "id": "stats_reset", "class": "table_obj_value"}'
    ']'
  '}]'::jsonb),
(1, 'dbstatmain', 'dbstat', 300, NULL, NULL, NULL, NULL, NULL,
'[{'
    '"type": "row_table",'
    '"source": "dbstat",'
    '"ordering": "ord_db",'
    '"highlight": ['
      '{"id": "dbname", "index": 0}'
    '],'
    '"columns": ['
      '{"caption": "База данных", "id": "dbname", "class": "table_obj_name"},'
      '{"caption": "Транзакции", "columns": ['
        '{"caption": "Зафиксировано", "id": "xact_commit", "class": "table_obj_value", '
          '"title": "Количество транзакций, зафиксированных в этой базе данных"},'
        '{"caption": "Отменено", "id": "xact_rollback", "class": "table_obj_value", '
          '"title": "Количество транзакций, отменённых в этой базе данных"},'
        '{"caption": "Взаимоблокировки", "id": "deadlocks", "class": "table_obj_value", '
          '"title": "Количество взаимоблокировок, обнаруженных в этой базе данных"}'
     ']},'
      '{"caption": "Контрольные суммы", "condition": "checksum_fail_detected", "columns": ['
        '{"caption": "Ошибки", "id": "checksum_failures", "class": "table_obj_value", '
          '"title": "Количество обнаруженных ошибок контрольных сумм блоков"},'
        '{"caption": "Последняя", "id": "checksum_last_failure", "class": "table_obj_value", '
          '"title": "Последняя обнаруженная ошибка контрольной суммы"}'
     ']},'
      '{"caption": "Статистика блоков", "columns": ['
        '{"caption": "Попадания (%)", "id": "blks_hit_pct", "class": "table_obj_value", '
          '"title": "Доля попаданий в буферный кеш"},'
        '{"caption": "Прочитано", "id": "blks_read", "class": "table_obj_value", '
          '"title": "Количество дисковых блоков, прочитанных в этой базе данных"},'
        '{"caption": "Попадания", "id": "blks_hit", "class": "table_obj_value", '
          '"title": "Количество случаев, когда дисковые блоки уже находились в буферном кеше"}'
     ']},'
      '{"caption": "Время I/O блоков", "condition": "io_times", "columns": ['
        '{"caption": "Чтение", "id": "blk_read_time", "class": "table_obj_value", '
          '"title": "Время чтения блоков файлов данных серверными процессами, в секундах"},'
        '{"caption": "Запись", "id": "blk_write_time", "class": "table_obj_value", '
          '"title": "Время записи блоков файлов данных серверными процессами, в секундах"}'
     ']},'
      '{"caption": "Строки", "columns": ['
        '{"caption": "Возвращено", "id": "tup_returned", "class": "table_obj_value", '
          '"title": "Количество строк, возвращённых запросами в этой базе данных"},'
        '{"caption": "Извлечено", "id": "tup_fetched", "class": "table_obj_value", '
          '"title": "Количество строк, извлечённых запросами в этой базе данных"},'
        '{"caption": "Вставлено", "id": "tup_inserted", "class": "table_obj_value", '
          '"title": "Количество строк, вставленных запросами в этой базе данных"},'
        '{"caption": "Обновлено", "id": "tup_updated", "class": "table_obj_value", '
          '"title": "Количество строк, обновлённых запросами в этой базе данных"},'
        '{"caption": "Удалено", "id": "tup_deleted", "class": "table_obj_value", '
          '"title": "Количество удалённых строк"}'
     ']},'
     '{"caption": "Параллельные рабочие процессы", "condition": "db_parallel_workers", "columns": ['
        '{"caption": "Запланировано", "id": "parallel_workers_to_launch", "class": "table_obj_value", '
          '"title": "Количество параллельных рабочих процессов, запланированных к запуску запросами в этой базе данных"},'
        '{"caption": "Запущено", "id": "parallel_workers_launched", "class": "table_obj_value", '
          '"title": "Количество параллельных рабочих процессов, запущенных запросами в этой базе данных"}'
     ']},'
      '{"caption": "Временные файлы", "columns": ['
        '{"caption": "Размер", "id": "temp_bytes", "class": "table_obj_value", '
          '"title": "Объём данных, записанных запросами во временные файлы в этой базе данных"},'
        '{"caption": "Файлы", "id": "temp_files", "class": "table_obj_value", '
          '"title": "Количество временных файлов, созданных запросами в этой базе данных"}'
     ']},'
     '{"caption": "Размер", "id": "datsize", "class": "table_obj_value", '
       '"title": "Размер базы данных на момент последнего снимка интервала отчёта"},'
     '{"caption": "Рост", "id": "datsize_delta", "class": "table_obj_value", '
       '"title": "Увеличение размера базы данных за интервал отчёта"}'
    ']'
  '}]'::jsonb),
(1, 'iostat', 'srvstat', 328, 'Статистика I/O кластера', 'Статистика I/O кластера', 'stat_io', NULL, NULL, NULL),
(1, 'iostatrst', 'srvstat', 329, NULL, NULL, 'stat_io_reset', NULL,
  '{"class": "warning", "text": "На интервале отчёта обнаружен сброс статистики I/O. Значения статистики могут быть искажены"}',
  '[{'
    '"type": "row_table",'
    '"source": "stat_io_reset",'
    '"ordering": "ord_sample",'
    '"columns": ['
      '{"caption": "ID снимка", "id": "sample_id", "class": "table_obj_name", '
        '"title": "Идентификатор снимка, в котором обнаружен сброс"},'
      '{"caption": "Объект", "id": "object", "class": "table_obj_name", '
        '"title": "Целевой объект операции I/O"},'
      '{"caption": "Серверный процесс", "id": "backend_type", "class": "table_obj_name", '
        '"title": "Тип серверного процесса (см. stat_activity)"},'
      '{"caption": "Контекст", "id": "context", "class": "table_obj_name", '
        '"title": "Контекст операции I/O"},'
      '{"caption": "Время сброса", "id": "stats_reset", "class": "table_obj_value", '
        '"title": "Дата и время последнего сброса на снимке"}'
    ']'
    '}]'::jsonb),
(1, 'iostatmain', 'srvstat', 330, NULL, NULL, 'stat_io', NULL, NULL,
'[{'
    '"type": "row_table",'
    '"source": "stat_io",'
    '"ordering": "ord_obj",'
    '"columns": ['
      '{"caption": "Объект", "id": "object", "class": "table_obj_name", '
        '"title": "Целевой объект операции I/O"},'
      '{"caption": "Серверный процесс", "id": "backend_type", "class": "table_obj_name", '
        '"title": "Тип серверного процесса (см. stat_activity)"},'
      '{"caption": "Контекст", "id": "context", "class": "table_obj_name", '
        '"title": "Контекст операции I/O"},'
      '{"caption": "Чтение", "columns": ['
        '{"caption": "Количество", "id": "reads", "class": "table_obj_value", '
          '"title": "Количество операций чтения"},'
        '{"caption": "Байты", "id": "read_sz", "class": "table_obj_value", '
          '"title": "Объём прочитанных данных"},'
        '{"caption": "Время", "id": "read_time", "class": "table_obj_value", '
          '"condition": "io_times", '
          '"title": "Время операций чтения (в секундах)"}'
     ']},'
      '{"caption": "Запись", "columns": ['
        '{"caption": "Количество", "id": "writes", "class": "table_obj_value", '
          '"title": "Количество операций записи"},'
        '{"caption": "Байты", "id": "write_sz", "class": "table_obj_value", '
          '"title": "Объём записанных данных"},'
        '{"caption": "Время", "id": "write_time", "class": "table_obj_value", '
          '"condition": "io_times", '
          '"title": "Время операций записи (в секундах)"}'
     ']},'
      '{"caption": "Обратная запись", "columns": ['
        '{"caption": "Количество", "id": "writebacks", "class": "table_obj_value", '
          '"title": "Количество блоков, которые процесс запросил у ядра записать в постоянное хранилище"},'
        '{"caption": "Байты", "id": "writeback_sz", "class": "table_obj_value", '
          '"title": "Объём данных, запрошенных для записи в постоянное хранилище"},'
        '{"caption": "Время", "id": "writeback_time", "class": "table_obj_value", '
          '"condition": "io_times", '
          '"title": "Время операций обратной записи (в секундах)"}'
     ']},'
      '{"caption": "Расширение", "columns": ['
        '{"caption": "Количество", "id": "extends", "class": "table_obj_value", '
          '"title": "Количество операций расширения отношений"},'
        '{"caption": "Байты", "id": "extend_sz", "class": "table_obj_value", '
          '"title": "Объём пространства, использованного операциями расширения"},'
        '{"caption": "Время", "id": "extend_time", "class": "table_obj_value", '
          '"condition": "io_times", '
          '"title": "Время операций расширения (в секундах)"}'
     ']},'
     '{"caption": "Попадания", "id": "hits", "class": "table_obj_value", '
       '"title": "Количество случаев, когда нужный блок был найден в общем буфере"},'
     '{"caption": "Вытеснения", "id": "evictions", "class": "table_obj_value", '
       '"title": "Количество случаев записи блока из общего или локального буфера для его повторного использования"},'
     '{"caption": "Повторное использование", "id": "reuses", "class": "table_obj_value", '
       '"title": "Количество повторных использований существующего буфера в кольцевом буфере ограниченного размера вне общих буферов при операциях I/O в контекстах bulkread, bulkwrite или vacuum"},'
      '{"caption": "Fsync", "columns": ['
        '{"caption": "Количество", "id": "fsyncs", "class": "table_obj_value", '
          '"title": "Количество вызовов fsync; учитываются только в контексте normal"},'
        '{"caption": "Время", "id": "fsync_time", "class": "table_obj_value", '
          '"condition": "io_times", '
          '"title": "Время операций fsync (в секундах)"}'
     ']}'
    ']'
    '}]'::jsonb),
(1, 'slrustat', 'srvstat', 358, 'Статистика SLRU кластера', 'Статистика SLRU кластера', 'stat_slru', NULL, NULL, NULL),
