    '}]'::jsonb),
(1, 'slrustatmain', 'slrustat', 360, NULL, NULL, 'stat_slru', NULL, NULL,
'[{'
    '"type": "row_table",'
    '"source": "stat_slru",'
    '"columns": ['
      '{"caption": "Имя", "id": "name", "class": "table_obj_name", '
        '"title": "Имя SLRU"},'
      '{"caption": "Обнулено", "id": "blks_zeroed", "class": "table_obj_value", '
        '"title": "Количество блоков, обнулённых при инициализации"},'
      '{"caption": "Попадания", "id": "blks_hit", "class": "table_obj_value", '
        '"title": "Количество случаев, когда дисковые блоки уже находились в SLRU и чтение '
        'не требовалось (учитываются только попадания в SLRU, но не в кеш файловой системы)"},'
      '{"caption": "Чтения", "id": "blks_read", "class": "table_obj_value", '
        '"title": "Количество дисковых блоков, прочитанных для этого SLRU"},'
      '{"caption": "Попадания (%)", "id": "hit_pct", "class": "table_obj_value", '
        '"title": "Доля попаданий по отношению к сумме чтений и попаданий для этого SLRU"},'
      '{"caption": "Записи", "id": "blks_written", "class": "table_obj_value", '
        '"title": "Количество дисковых блоков, записанных для этого SLRU"},'
      '{"caption": "Проверено", "id": "blks_exists", "class": "table_obj_value", '
        '"title": "Количество проверок существования блоков для этого SLRU (поле blks_exists)"},'
      '{"caption": "Сбросы", "id": "flushes", "class": "table_obj_value", '
        '"title": "Количество сбросов грязных данных для этого SLRU"},'
      '{"caption": "Усечения", "id": "truncates", "class": "table_obj_value", '
        '"title": "Количество усечений для этого SLRU"}'
    ']'
    '}]'::jsonb),
(1, 'sesstat', 'srvstat', 400, 'Статистика сеансов по базам данных', 'Статистика сеансов по базам данных', 'sess_stats', NULL, NULL,
'[{'
    '"type": "row_table",'
    '"source": "dbstat",'
    '"ordering": "ord_db",'
    '"highlight": ['
      '{"id": "dbname", "index": 0}'
    '],'
    '"columns": ['
      '{"caption": "База данных", "id": "dbname", "class": "table_obj_name"},'
