      '{"caption": "Тип блокировки", "id": "locktype", "class": "table_obj_name", '
        '"title": "Тип блокируемого объекта"},'
      '{"caption": "Ожидания", "columns": ['
        '{"caption": "Количество", "id": "waits", "class": "table_obj_value", '
          '"title": "Количество ожиданий блокировки этого типа из-за конфликта. Учитываются только успешно полученные блокировки после ожидания дольше deadlock_timeout"},'
        '{"caption": "%Всего", "id": "waits_pct", "class": "table_obj_value", '
          '"title": "Доля ожидавших блокировок этого типа от общего числа блокировок в кластере"}'
     ']},'
      '{"caption": "Время ожидания", "columns": ['
        '{"caption": "Время (мс)", "id": "wait_time", "class": "table_obj_value", '
          '"title": "Общее время ожидания блокировок этого типа; учитываются только успешно полученные блокировки после ожидания дольше deadlock_timeout"},'
        '{"caption": "%Всего", "id": "wait_time_pct", "class": "table_obj_value", '
          '"title": "Доля времени ожидания блокировок этого типа от общего времени блокировок в кластере"}'
     ']},'
      '{"caption": "Превышение fast-path", "columns": ['
        '{"caption": "Количество", "id": "fastpath_exceeded", "class": "table_obj_value", '
          '"title": "Количество случаев, когда блокировку этого типа не удалось получить по fast-path из-за нехватки слотов. Увеличение max_locks_per_transaction может уменьшить это число"},'
        '{"caption": "%Всего", "id": "fastpath_exceeded_pct", "class": "table_obj_value", '
          '"title": "Доля fast-path-блокировок этого типа от общего числа блокировок в кластере"}'
     ']}'
    ']'
    '}]'::jsonb),
(1, 'wait_sampling_srvstats', 'srvstat', 1500, 'Выборка ожиданий', 'Выборка ожиданий', 'wait_sampling_tot', NULL, NULL, NULL),
(1, 'wait_sampling_total', 'wait_sampling_srvstats', 100, 'Типы событий ожидания', 'Типы событий ожидания', 'wait_sampling_tot', NULL, NULL,
  '[{'
    '"type": "row_table", '
    '"source": "wait_sampling_total_stats",'
    '"ordering": "event_type_order",'
    '"columns": ['
      '{"id": "event_type", "class": "table_obj_name", "caption": "Тип события ожидания"}, '
