      '{"id": "stmt_waited_pct", "class": "table_obj_value", "title": "Доля ожиданий событий этого типа от общего времени ожидания при выполнении операторов в кластере", "caption": "%Всего"}, '
      '{"id": "tot_waited", "class": "table_obj_value", "title": "Время ожидания событий этого типа всеми серверными процессами, включая фоновые, в секундах", "caption": "Общее время ожидания (с)"}, '
      '{"id": "tot_waited_pct", "class": "table_obj_value", "title": "Доля ожиданий событий этого типа от общего времени ожидания всех серверных процессов кластера, включая фоновые", "caption": "%Всего"}'
    ']}]'::jsonb),
(1, 'wait_sampling_statements', 'wait_sampling_srvstats', 200, 'Основные события ожидания (операторы)', 'Основные события ожидания (операторы)', 'wait_sampling_tot', NULL,
 '{"class": "notice", "text": "Основные события ожидания при выполнении операторов"}',
  '[{'
    '"type": "row_table", '
    '"source": "wait_sampling_events",'
    '"filter": {"type": "exists", "field": "stmt_filter"},'
    '"ordering": "-stmt_waited",'
    '"limit": "topn",'
