      '{"id": "event", "class": "table_obj_name", "caption": "Событие ожидания"}, '
      '{"id": "stmt_waited", "class": "table_obj_value", "title": "Время ожидания события при выполнении операторов, в секундах", "caption": "Ожидание (с)"}, '
      '{"id": "stmt_waited_pct", "class": "table_obj_value", "title": "Доля ожидания события от общего времени ожидания при выполнении операторов в кластере", "caption": "%Всего"}'
  ']}]'::jsonb),
(1, 'wait_sampling_all', 'wait_sampling_srvstats', 300, 'Основные события ожидания (все)', 'Основные события ожидания (все)', 'wait_sampling_tot', NULL,
 '{"class": "notice", "text": "Основные события ожидания во всех серверных процессах"}',
  '[{'
    '"type": "row_table", '
    '"source": "wait_sampling_events",'
    '"filter": {"type": "exists", "field": "total_filter"},'
    '"ordering": "-tot_waited",'
    '"limit": "topn",'
    '"columns": ['
      '{"id": "event_type", "class": "table_obj_name", "caption": "Тип события ожидания"}, '
      '{"id": "event", "class": "table_obj_name", "caption": "Событие ожидания"}, '
      '{"id": "tot_waited", "class": "table_obj_value", "title": "Время ожидания события всеми серверными процессами, включая фоновые, в секундах", "caption": "Ожидание (с)"}, '
      '{"id": "tot_waited_pct", "class": "table_obj_value", "title": "Доля ожидания события от общего времени ожидания всех серверных процессов кластера, включая фоновые", "caption": "%Всего"}'
  ']}]'::jsonb)
;

