-- Query section of regular report
INSERT INTO report_struct (
  report_id, sect_id, parent_sect_id, s_ord, toc_cap, tbl_cap, feature, function_name,
  content, sect_struct)
VALUES
(1, 'sqlela', 'sqlsthdr', 100, 'SQL по общему времени', 'Основные SQL-запросы по общему времени', 'planning_times', NULL, NULL,
  '[{'
    '"type": "row_table", '
    '"source": "top_statements",'
    '"ordering": "ord_total_time",'
    '"highlight": ['
      '{"id": "hexqueryid", "index": 0},'
      '{"id": "queryid", "index": 1},'
      '{"id": "dbname", "index": 1},'
      '{"id": "username", "index": 1}'
    '],'
    '"preview": ['
      '{"id": "hexqueryid", "dataset": "queries"}'
    '],'
    '"filter": {"type": "exists", "field": "total_time"},'
    '"limit": "topn",'
    '"columns": ['
      '{"id": "hexqueryid", "class": "table_obj_name queryId", "caption": "ID запроса"}, '
      '{"id": "dbname", "class": "table_obj_name", "caption": "База данных"}, '
      '{"id": "username", "class": "table_obj_name", "caption": "Пользователь"}, '
      '{"id": "total_time_pct", "class": "table_obj_value", "title": "Доля общего времени оператора от общего времени всех операторов кластера", "caption": "%Всего"}, '
      '{"caption": "Время (с)", "columns": ['
        '{"id": "total_time", "class": "table_obj_value", "title": "Время, затраченное оператором", "caption": "Общее время"}, '
        '{"id": "total_plan_time", "class": "table_obj_value", "title": "Время планирования оператора", "caption": "Планирование"}, '
        '{"id": "total_exec_time", "class": "table_obj_value", "title": "Время выполнения оператора", "caption": "Выполнение"}'
        ']}, '
      '{"id": "jit_total_time", "class": "jitTimeCell", "caption": "JIT, время (с)", "condition": "statements_jit_stats"}, '
      '{"class": "table_obj_name", "caption": "Время I/O (с)", "condition": "io_times", "columns": ['
        '{"id": "shared_blk_read_time", "class": "table_obj_value", "title": "Время чтения блоков оператором", "caption": "Чтение"}, '
        '{"id": "shared_blk_write_time", "class": "table_obj_value", "title": "Время записи блоков оператором", "caption": "Запись"}'
        ']}, '
      '{"class": "table_obj_name", "caption": "Время CPU (с)", "condition": "kcachestatements", "columns": ['
        '{"id": "user_time", "class": "table_obj_value", "caption": "Пользовательское"}, '
        '{"id": "system_time", "class": "table_obj_value", "caption": "Системное"}'
        ']}, '
      '{"id": "plans", "class": "table_obj_value", "caption": "Планы", "title": "Количество планирований оператора"}, '
      '{"id": "calls", "class": "table_obj_value", "caption": "Выполнения", "title": "Количество выполнений оператора"}, '
      '{"id": "stmt_cover", "class": "table_obj_value", "condition": "statements_coverage", "caption": "%Покрытия", "title": "Покрытие: длительность сбора статистики операторов в процентах от длительности отчёта"} '
    ']'
  '}]'::jsonb),
(1, 'sqlplan', 'sqlsthdr', 200, 'SQL по времени планирования', 'Основные SQL-запросы по времени планирования', 'planning_times', NULL, NULL,
  '[{'
    '"type": "row_table", '
    '"source": "top_statements",'
    '"ordering": "ord_plan_time",'
    '"highlight": ['
      '{"id": "hexqueryid", "index": 0},'
      '{"id": "queryid", "index": 1},'
      '{"id": "dbname", "index": 1},'
      '{"id": "username", "index": 1}'
    '],'
    '"preview": ['
      '{"id": "hexqueryid", "dataset": "queries"}'
    '],'
    '"filter": {"type": "exists", "field": "total_plan_time"},'
    '"limit": "topn",'
    '"columns": ['
      '{"id": "hexqueryid", "class": "table_obj_name queryId", "caption": "ID запроса"}, '
      '{"id": "dbname", "class": "table_obj_name", "caption": "База данных"}, '
      '{"id": "username", "class": "table_obj_name", "caption": "Пользователь"}, '
      '{"id": "total_plan_time", "class": "table_obj_value", "title": "Время планирования оператора", "caption": "Время планирования (с)"}, '
