     '{"caption": "Впервые обнаружено", "condition": "extension_versions_show_date_columns", "id": "first_seen", "class": "table_obj_value", "title": "Первое появление этой версии расширения"},'
     '{"caption": "Последний раз обнаружено", "condition": "extension_versions_show_date_columns", "id": "last_seen", "class": "table_obj_value", "title": "Последнее появление этой версии расширения"},'
     '{"caption": "Версия", "id": "extversion", "class": "table_obj_value", "title": "Версия расширения"}'
    ']'
  '}]'::jsonb)
;

