        '{"id": ["1", "2"], "class": "interval", "title":["properties.timePeriod1", "properties.timePeriod2"], "caption": "Интервал"},'
        '{"caption": "Интервал (снимки)", "columns": ['
          '{"id": ["start1_id", "start2_id"], "class": "table_obj_value", "caption": "начало"},'
          '{"id": ["end1_id", "end2_id"], "class": "table_obj_value", "caption": "конец"}'
