(2, 'vachdr', NULL, 700, 'Статистика очистки', 'Статистика очистки', NULL, NULL, NULL, NULL),
(2, 'settings', NULL, 800, 'Параметры кластера', 'Параметры кластера на интервале отчёта', NULL, NULL, NULL, NULL),
(2, 'extensions', NULL, 850, 'Версии расширений', 'Версии расширений на интервале отчёта', NULL, NULL, NULL, NULL),
(2, 'stmt_warn', NULL, 900, NULL, 'Предупреждение!', 'stmt_cnt_all', NULL, NULL,
  '[{'
