-- Server section of differential report
INSERT INTO report_struct (
  report_id, sect_id, parent_sect_id, s_ord, toc_cap, tbl_cap, feature, function_name, content,
  sect_struct)
VALUES
(2, 'dbstat', 'srvstat', 100, 'Статистика баз данных', 'Статистика баз данных', NULL, NULL, NULL, NULL),
(2, 'dbstatreset', 'dbstat', 200, NULL, NULL, 'dbstats_reset', NULL,
  '{"class": "warning", "text": "На интервале отчёта обнаружен сброс статистики баз данных! Значения для перечисленных баз данных '
  'и содержащихся в них объектов могут быть искажены."}',
  '[{'
    '"type": "row_table", '
    '"source": "dbstats_reset", '
    '"ordering": "ord_sample",'
    '"columns": ['
        '{"id": "dbname", "class": "table_obj_name", "caption": "База данных"}, '
        '{"id": "sample_id", "class": "table_obj_value", "caption": "Снимок"}, '
        '{"id": "stats_reset", "class": "table_obj_value", "caption": "Время сброса"}'
    ']'
  '}]'::jsonb),
(2, 'dbstatmain', 'dbstat', 300, NULL, NULL, NULL, NULL, NULL,
'[{'
    '"type": "row_table", '
    '"source": "dbstat", '
    '"ordering": "ord_db",'
    '"highlight": ['
      '{"id": "dbname", "index": 0}'
    '],'
    '"columns": ['
        '{"id": "dbname", "class": "table_obj_name hdr", "caption": "База данных", "rowspan": true}, '
        '{"id": ["1", "2"], "class": "interval", "title":["properties.timePeriod1", "properties.timePeriod2"], "caption": "Интервал"}, '
        '{"caption": "Транзакции", "columns": ['
            '{"id": ["xact_commit1", "xact_commit2"], "class": "table_obj_value", "title": "Количество транзакций, зафиксированных в этой базе данных", "caption": "Зафиксировано"}, '
            '{"id": ["xact_rollback1", "xact_rollback2"], "class": "table_obj_value", "title": "Количество транзакций, отменённых в этой базе данных", "caption": "Отменено"}, '
            '{"id": ["deadlocks1", "deadlocks2"], "class": "table_obj_value", "title": "Количество взаимоблокировок, обнаруженных в этой базе данных", "caption": "Взаимоблокировки"}'
        ']}, '
        '{"caption": "Контрольные суммы", "condition": "checksum_fail_detected", "columns": ['
            '{"id": ["checksum_failures1", "checksum_failures2"], "class": "table_obj_value", "title": "Количество обнаруженных ошибок контрольных сумм блоков", "caption": "Ошибки"}, '
            '{"id": ["checksum_last_failure1", "checksum_last_failure2"], "class": "table_obj_value", "title": "Последняя обнаруженная ошибка контрольной суммы", "caption": "Последняя"}
            ]}, '
        '{"caption": "Статистика блоков", "columns": ['
            '{"id": ["blks_hit_pct1", "blks_hit_pct2"], "class": "table_obj_value", "title": "Доля попаданий в буферный кеш", "caption": "Попадания (%)"}, '
            '{"id": ["blks_read1", "blks_read2"], "class": "table_obj_value", "title": "Количество дисковых блоков, прочитанных в этой базе данных", "caption": "Чтение"}, '
            '{"id": ["blks_hit1", "blks_hit2"], "class": "table_obj_value", "title": "Количество случаев, когда дисковые блоки уже находились в буферном кеше", "caption": "Попадания"}'
        ']}, '
        '{"caption": "Время I/O блоков", "condition": "io_times", "columns": ['
            '{"id": ["blk_read_time1", "blk_read_time2"], "class": "table_obj_value", "title": "Время чтения блоков файлов данных серверными процессами", "caption": "Чтение"}, '
            '{"id": ["blk_write_time1", "blk_write_time2"], "class": "table_obj_value", "title": "Время записи блоков файлов данных серверными процессами", "caption": "Запись"} '
        ']}, '
        '{"caption": "Строки", "columns": ['
            '{"id": ["tup_returned1", "tup_returned2"], "class": "table_obj_value", "title": "Количество строк, возвращённых запросами в этой базе данных", "caption": "Возвращено"}, '
            '{"id": ["tup_fetched1", "tup_fetched2"], "class": "table_obj_value", "title": "Количество строк, извлечённых запросами в этой базе данных", "caption": "Извлечено"}, '
            '{"id": ["tup_inserted1", "tup_inserted2"], "class": "table_obj_value", "title": "Количество строк, вставленных запросами в этой базе данных", "caption": "Вставлено"}, '
            '{"id": ["tup_updated1", "tup_updated2"], "class": "table_obj_value", "title": "Количество строк, обновлённых запросами в этой базе данных", "caption": "Обновлено"}, '
            '{"id": ["tup_deleted1", "tup_deleted2"], "class": "table_obj_value", "title": "Количество удалённых строк", "caption": "Удалено"}'
        ']},'
        '{"caption": "Параллельные рабочие процессы", "condition": "db_parallel_workers", "columns": ['
           '{"id": ["parallel_workers_to_launch1", "parallel_workers_to_launch2"], "class": "table_obj_value", "title": "Количество параллельных рабочих процессов, запланированных запросами в этой базе данных", "caption": "Запланировано"},'
           '{"id": ["parallel_workers_launched1", "parallel_workers_launched2"], "class": "table_obj_value", "title": "Количество параллельных рабочих процессов, запущенных запросами в этой базе данных", "caption": "Запущено"}'
        ']}, '
        '{"caption": "Временные файлы", "columns": ['
            '{"id": ["temp_bytes1", "temp_bytes2"], "class": "table_obj_value", "title": "Объём данных, записанных запросами во временные файлы этой базы данных", "caption": "Размер"}, '
            '{"id": ["temp_files1", "temp_files2"], "class": "table_obj_value", "title": "Количество временных файлов, созданных запросами в этой базе данных", "caption": "Файлы"}'
        ']}, '
        '{"id": ["datsize1", "datsize2"], "class": "table_obj_value", "title": "Размер базы данных на момент последнего снимка интервала отчёта", "caption": "Размер"}, '
        '{"id": ["datsize_delta1", "datsize_delta2"], "class": "table_obj_value", "title": "Увеличение размера базы данных за интервал отчёта", "caption": "Рост"} '
']}]'::jsonb),
(2, 'iostat', 'srvstat', 328, 'Статистика I/O кластера', 'Статистика I/O кластера', 'stat_io', NULL, NULL, NULL),
(2, 'iostatrst', 'srvstat', 329, NULL, NULL, 'stat_io_reset', NULL,
