      '{"caption": "Время сброса", "id": "stats_reset", "class": "table_obj_value", '
        '"title": "Дата и время последнего сброса на снимке"}'
    ']'
    '}]'::jsonb),
(2, 'iostatmain', 'srvstat', 330, NULL, NULL, 'stat_io', NULL, NULL,
'[{'
    '"type": "row_table",'
    '"source": "stat_io",'
    '"ordering": "ord_obj",'
    '"columns": ['
      '{"caption": "Объект", "id": "object", "class": "table_obj_name hdr", "rowspan": true, '
        '"title": "Целевой объект операции I/O"},'
      '{"caption": "Серверный процесс", "id": "backend_type", "class": "table_obj_name hdr", "rowspan": true, '
        '"title": "Тип серверного процесса (см. stat_activity)"},'
      '{"caption": "Контекст", "id": "context", "class": "table_obj_name hdr", "rowspan": true, '
        '"title": "Контекст операции I/O"},'
      '{"id": ["1", "2"], "class": "interval", "title":["properties.timePeriod1", "properties.timePeriod2"], "caption": "Интервал"},'
      '{"caption": "Чтения", "columns": ['
