        '{"caption": "Байты", "id": ["read_sz1", "read_sz2"], "class": "table_obj_value", '
          '"title": "Объём прочитанных данных"},'
        '{"caption": "Время", "id": ["read_time1", "read_time2"], "class": "table_obj_value", '
          '"condition": "io_times", '
          '"title": "Время операций чтения (в секундах)"}'
     ']},'
      '{"caption": "Записи", "columns": ['
        '{"caption": "Количество", "id": ["writes1", "writes2"], "class": "table_obj_value", '
          '"title": "Количество операций записи"},'
        '{"caption": "Байты", "id": ["write_sz1", "write_sz2"], "class": "table_obj_value", '
          '"title": "Объём записанных данных"},'
        '{"caption": "Время", "id": ["write_time1", "write_time2"], "class": "table_obj_value", '
          '"condition": "io_times", '
          '"title": "Время операций записи (в секундах)"}'
     ']},'
      '{"caption": "Обратная запись", "columns": ['
        '{"caption": "Количество", "id": ["writebacks1", "writebacks2"], "class": "table_obj_value", '
          '"title": "Количество блоков, которые процесс запросил у ядра записать в постоянное хранилище"},'
        '{"caption": "Байты", "id": ["writeback_sz1", "writeback_sz2"], "class": "table_obj_value", '
          '"title": "Объём данных, запрошенных для записи в постоянное хранилище"},'
        '{"caption": "Время", "id": ["writeback_time1", "writeback_time2"], "class": "table_obj_value", '
          '"condition": "io_times", '
          '"title": "Время операций обратной записи (в секундах)"}'
     ']},'
      '{"caption": "Расширения", "columns": ['
        '{"caption": "Количество", "id": ["extends1", "extends2"], "class": "table_obj_value", '
          '"title": "Количество операций расширения отношений"},'
        '{"caption": "Байты", "id": ["extend_sz1", "extend_sz2"], "class": "table_obj_value", '
          '"title": "Объём пространства, использованного операциями расширения"},'
        '{"caption": "Время", "id": ["extend_time1", "extend_time2"], "class": "table_obj_value", '
          '"condition": "io_times", '
          '"title": "Время операций расширения (в секундах)"}'
     ']},'
     '{"caption": "Попадания", "id": ["hits1", "hits2"], "class": "table_obj_value", '
       '"title": "Количество случаев, когда нужный блок был найден в общем буфере"},'
     '{"caption": "Вытеснения", "id": ["evictions1", "evictions2"], "class": "table_obj_value", '
       '"title": "Количество вытеснений блока из общего или локального буфера для повторного использования"},'
     '{"caption": "Повторное использование", "id": ["reuses1", "reuses2"], "class": "table_obj_value", '
       '"title": "Количество повторных использований существующего буфера в кольцевом буфере ограниченного размера при операциях I/O в контекстах bulkread, bulkwrite или vacuum"},'
      '{"caption": "Fsync", "columns": ['
