(2, 'slrustatmain', 'slrustat', 360, NULL, NULL, 'stat_slru', NULL, NULL,
'[{'
    '"type": "row_table",'
    '"source": "stat_slru",'
    '"columns": ['
      '{"caption": "Имя", "id": "name", "class": "table_obj_name hdr", "rowspan": true, '
        '"title": "Имя SLRU"},'
      '{"id": ["1", "2"], "class": "interval", "title":["properties.timePeriod1", "properties.timePeriod2"], "caption": "Интервал"},'
      '{"caption": "Обнулено", "id": ["blks_zeroed1", "blks_zeroed2"], "class": "table_obj_value", '
        '"title": "Количество блоков, обнулённых при инициализации"},'
      '{"caption": "Попадания", "id": ["blks_hit1", "blks_hit2"], "class": "table_obj_value", '
