        '{"caption": "Время (с)", "columns": ['
          '{"id": ["session_time1", "session_time2"], "class": "table_obj_value", "title": "Время сеансов этой базы данных (статистика обновляется только при изменении состояния сеанса, поэтому длительный простой может не учитываться)", "caption": "Всего"},'
          '{"id": ["active_time1", "active_time2"], "class": "table_obj_value", "title": "Время выполнения SQL-операторов в этой базе данных (состояния active и fastpath function call в pg_stat_activity)", "caption": "Активные"},'
          '{"id": ["idle_in_transaction_time1", "idle_in_transaction_time2"], "class": "table_obj_value", "title": "Время простоя в транзакции в этой базе данных (состояния idle in transaction и idle in transaction (aborted))", "caption": "Простой (транзакция)"}'
        ']},'
        '{"caption": "Сеансы", "columns": ['
