          '{"id": ["sessions_abandoned1", "sessions_abandoned2"], "class": "table_obj_value", "title": "Количество сеансов этой базы данных, завершённых из-за потери соединения с клиентом", "caption": "Разорвано"},'
          '{"id": ["sessions_fatal1", "sessions_fatal2"], "class": "table_obj_value", "title": "Количество сеансов этой базы данных, завершённых из-за критических ошибок", "caption": "Аварийно завершено"},'
          '{"id": ["sessions_killed1", "sessions_killed2"], "class": "table_obj_value", "title": "Количество сеансов этой базы данных, завершённых оператором", "caption": "Принудительно завершено"}'
        ']}'
    ']}]'::jsonb),
